<template><div class="page"><div class="page-head"><div><h2>风险事件</h2><p>风险事件支持分派、处理、审核和关闭，形成完整处置闭环。</p></div><div><el-input-number v-model="filter.companyId" :min="1" style="width:120px;margin-right:8px"/><el-select v-model="filter.level" clearable placeholder="等级" style="width:110px;margin-right:8px"><el-option label="高" value="HIGH"/><el-option label="中" value="MEDIUM"/><el-option label="低" value="LOW"/></el-select><el-select v-model="filter.status" clearable placeholder="状态" style="width:130px;margin-right:8px"><el-option v-for="x in statuses" :key="x" :value="x"/></el-select><el-button @click="load">查询</el-button></div></div><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="eventNo" label="事件编号" width="170"/><el-table-column prop="companyId" label="企业ID" width="80"/><el-table-column prop="riskTitle" label="风险标题" min-width="190"/><el-table-column prop="riskType" label="类型"/><el-table-column prop="riskLevel" label="等级" width="80"><template #default="s"><el-tag :type="tag(s.row.riskLevel)">{{s.row.riskLevel}}</el-tag></template></el-table-column><el-table-column prop="triggerValue" label="触发值"/><el-table-column prop="thresholdValue" label="阈值"/><el-table-column prop="status" label="状态" width="110"/><el-table-column prop="assigneeUserId" label="处理人" width="90"/><el-table-column label="操作" min-width="220"><template #default="s"><el-button link v-if="auth.has('risk:assign')" @click="action('assign',s.row)">分派</el-button><el-button link v-if="auth.has('risk:handle')" @click="action('handle',s.row)">处理</el-button><el-button link v-if="auth.has('risk:review')" @click="action('review',s.row)">审核</el-button><el-button link type="success" v-if="auth.has('risk:close')" @click="close(s.row)">关闭</el-button></template></el-table-column></el-table>
<el-dialog v-model="visible" :title="dialogTitle" width="520px"><el-form label-width="90px"><el-form-item v-if="mode==='assign'" label="处理人ID"><el-input-number v-model="actionForm.assigneeUserId" :min="1"/></el-form-item><el-form-item v-if="mode==='handle'" label="处理结果"><el-input type="textarea" :rows="5" v-model="actionForm.handleResult"/></el-form-item><template v-if="mode==='review'"><el-form-item label="审核意见"><el-input type="textarea" :rows="4" v-model="actionForm.reviewComment"/></el-form-item><el-form-item label="审核通过"><el-switch v-model="actionForm.approved"/></el-form-item></template></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="submit">提交</el-button></template></el-dialog></div></template>
<script setup>import{ref,computed,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{api}from'../api';import{useAuthStore}from'../stores/auth';const auth=useAuthStore(),rows=ref([]),loading=ref(false),visible=ref(false),mode=ref(''),current=ref(null);const statuses=['OPEN','PENDING','ASSIGNED','HANDLED','REVIEWED','CLOSED','REJECTED'];const filter=ref({companyId:null,level:'',status:''}),actionForm=ref({});const dialogTitle=computed(()=>({assign:'分派风险',handle:'填写处理结果',review:'审核风险'}[mode.value]||''));function tag(l){return l==='HIGH'?'danger':l==='MEDIUM'?'warning':'success'}async function load(){loading.value=true;try{let p={...filter.value};Object.keys(p).forEach(k=>!p[k]&&delete p[k]);rows.value=(await api.risks(p))||[]}finally{loading.value=false}}function action(m,r){mode.value=m;current.value=r;actionForm.value=m==='assign'?{assigneeUserId:r.assigneeUserId||4}:m==='handle'?{handleResult:r.handleResult||''}:{reviewComment:r.reviewComment||'',approved:true};visible.value=true}async function submit(){const id=current.value.id;if(mode.value==='assign')await api.assignRisk(id,actionForm.value);if(mode.value==='handle')await api.handleRisk(id,actionForm.value);if(mode.value==='review')await api.reviewRisk(id,actionForm.value);ElMessage.success('操作成功');visible.value=false;load()}async function close(r){await ElMessageBox.confirm('确认关闭该风险事件？','提示');await api.closeRisk(r.id);ElMessage.success('已关闭');load()}onMounted(load)</script>
